pub fn requirement(isa: &str) -> Features {
    let mut f = Features::NONE;
    match isa {
        "AVX" => f.avx = true,
        "AVX2" | "AVX2GATHER" => {
            f.avx = true;
            f.avx2 = true
        }
        "FMA" => {
            f.avx = true;
            f.fma = true
        }
        "F16C" => {
            f.avx = true;
            f.f16c = true
        }
        "LZCNT" => f.lzcnt = true,
        "MOVBE" => f.movbe = true,
        "XSAVE" => f.xsave = true,
        _ => unreachable!(),
    }
    f
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V3Operand {
    X,
    Y,
    D,
    Q,
    M(u16),
    I,
}
impl V3Operand {
    pub fn matches(self, o: &Operand) -> bool {
        use V3Operand::*;
        match (self, o) {
            (X, Operand::Register(r)) => r.class == RegisterClass::Xmm,
            (Y, Operand::Register(r)) => r.class == RegisterClass::Ymm,
            (D, Operand::Register(r)) => r.class == RegisterClass::Gpr && r.width == 32,
            (Q, Operand::Register(r)) => r.class == RegisterClass::Gpr && r.width == 64,
            (M(w), Operand::Memory(m)) => m.width == 0 || m.width == w,
            (I, Operand::Immediate(_)) => true,
            _ => false,
        }
    }
}
#[derive(Clone, Copy, Debug)]
pub struct V3Form {
    pub opcode: Opcode,
    pub isa: &'static str,
    pub map: u8,
    pub pp: u8,
    pub byte: u8,
    pub l: bool,
    pub w: bool,
    pub operands: &'static [V3Operand],
    pub field: i8,
    pub digit: u8,
    pub source: i8,
    pub rm: i8,
    pub imm: i8,
    pub imm_reg: bool,
    pub vsib: u16,
}
impl V3Form {
    pub fn matches(&self, i: &super::Instruction) -> bool {
        self.opcode==i.opcode && self.operands.len()==i.operands.len()
        && self.operands.iter().zip(&i.operands).all(|(s,o)|s.matches(o))
        && (self.vsib==0 || i.operands.iter().any(|o|matches!(o, Operand::Memory(m) if m.index.is_some_and(|r|r.width==self.vsib && matches!(r.class,RegisterClass::Xmm | RegisterClass::Ymm)))))
    }
}
pub fn form(i: &super::Instruction) -> Option<&'static V3Form> {
    V3_FORMS
        .iter()
        .filter(|f| f.matches(i))
        .min_by_key(|f| (u8::from(f.w), f.map))
}
